proof.raw:
We recall here the expression of the differential operator $ \mathcal{L}_c^{(\alpha)}$  :
$$
\mathcal L_c^{(\alpha)} (f)(x)= -\frac{1}{\omega_{\alpha}(x)} \frac{d}{dx}\left[ \omega_{\alpha}(x) (1-x^2) f'(x)\right] +c^2 x^2  f(x) = -(1-x^2)f''(x) + 2(\alpha+1)xf'(x) + c^2x^2f(x) .$$
For any positive integer $r$ and function $ f\in H^r_{\alpha,0}$ , the derivatives of $ \mathcal{L}_c^{(\alpha)}.f$ are given by :

\begin{eqnarray}
\frac{d^r}{dx^r}[\mathcal{L}_c^{(\alpha)}.f](x) &=& -(1-x^2) \frac{d^{r+2}f}{dx^{r+2}}(x) + 2(r+\alpha+1)x\frac{d^{r+1}f}{dx^{r+1}}(x) + \Big[ r(2\alpha + r +1)+c^2 x^2 \Big] \frac{d^{r}f}{dx^{r}}(x) \nonumber \\
&+& 2 c^2rx \frac{d^{r-1}f}{dx^{r-1}}(x) + c^2  r(r-1) \frac{d^{r-2}f}{dx^{r-2}}(x)
\end{eqnarray}
This expression yields directly that :
\begin{eqnarray}
\norm{\mathcal{L}_c^{(\alpha)}.f}^2_{\alpha,r} &=& \sum_{m=0}^r \norm{\frac{d^r}{dx^r}[\mathcal{L}_c^{(\alpha)}.f]}^2_{L^2(I,\omega_\alpha)} \nonumber \\
& \leq C & \norm{f}^2_{\alpha,r+2}
\end{eqnarray}
Therefore $\mathcal{L}_c^{(\alpha)}$ is a continuous operator from $ H^{r+2}_{\alpha,0}(I)$ into $ H^r_{\alpha,0}(I)$. \\
Then, by induction on $ r $, we obtain
\begin{equation}
\norm{\Big[\mathcal{L}_c^{(\alpha)}\Big]^r.f}_{\alpha,s} \leq C \norm{f}_{\alpha,r+2}
\end{equation}
For $ f \in H^r_{\alpha}(I) $, we write :
$$ f = \sum_{n=0}^{\infty} \hat{f_n}\psi^{(\alpha)}_{n,c} \quad \mbox{with} \quad
\hat{f_n} = \int_{-1}^1 f(x) \psi^{(\alpha)}_{n,c}(x) \omega_{\alpha}(x) $$
Since $\mathcal{L}_c^{(\alpha)}$ is self adjoint on $L^2(I,\omega_{\alpha}) $,
\begin{eqnarray}
\hat{f_n} &=& \frac{1}{\chi_{n,\alpha}}\int_{-1}^1 \mathcal{L}_c^{(\alpha)}.\psi_{n,c}^{(\alpha)}(x) f(x) \omega_{\alpha}(x) dx =  \frac{1}{\chi_{n,\alpha}}\int_{-1}^1 \mathcal{L}_c^{(\alpha)}.f(x) \psi_{n,c}^{(\alpha)}(x)  \omega_{\alpha}(x) dx \nonumber \\
&=& ... = \frac{1}{(\chi_{n,\alpha})^r}\int_{-1}^1 \Big[\mathcal{L}_c^{(\alpha)}\Big]^r.f(x) \psi_{n,c}^{(\alpha)}(x)  \omega_{\alpha}(x) dx
\end{eqnarray}
Thus
\begin{eqnarray}
|\hat{f_n}|^2 &=& \frac{1}{\Big(\chi_{n}^{(\alpha)}\Big)^{2r}}|\Big<\Big[\mathcal{L}_c^{(\alpha)}\Big]^r.f,\psi_{n,c}^{(\alpha)}\Big>_{L^2(I,\omega_{\alpha})}|^2 \leq \frac{1}{\Big(\chi_{n}^{(\alpha)}\Big)^{2r}} \norm{\Big[\mathcal{L}_c^{(\alpha)}\Big]^rf}_{L^2(I,\omega_{\alpha})} \nonumber \\
&\leq & \frac{C}{\Big(\chi_{n}^{(\alpha)}\Big)^{2r}} \norm{f}^2_{r+2,\alpha}
\end{eqnarray}
By writing $ \norm{f-S_Nf}^2_{L^2(I,\omega_\alpha)} = \displaystyle \sum_{n=N+1}^{\infty} |\hat{f_n}|^2 $ one gets \eqref{approx1}
Then, we obtain the result for $u$ regular, then for $ u \in H^{r+2}_{\alpha} (I)$ by density and continuity. Finally, for $s$ between two even integers, we conclude by interpolation.

By $(\ref{9})$ ,$(\ref{Eq3.1})$  , the inequality   $\chi_{n}^{\alpha}(c)\leq n(n+2\alpha+1)+c^2$ and  the previous remark,
one concludes that for $c>0$ and $\alpha  >-1$, and  for all positive integers $n,\; k$ such that, $k\leq n/A$ and $n\geq Ac$ with $A\geq 1.9$, we have,
\begin{eqnarray}

|\beta_k^n|  &\leq &C_{\alpha}\left(\frac{2\sqrt{\chi_{n}^{\alpha}(c)}}{c} \right)^k |\mu_{n}^{\alpha}(c)|\nonumber\\
	&\leq &\frac{C_{\alpha}}{c^{\frac{({\alpha+2})}{2}}\log(\frac{2n-1}{ec})}
	\left(\frac{2}{c}\sqrt{\left({n(n+2\alpha+1)+c^2}\right)} \right)^{{k}}\left(\frac{ec}{2n-1}\right)^{n+\frac{\alpha}{2}} \nonumber\\
	&\leq &\frac{C_{\alpha}\left(\frac{ec}{2n-1}\right)^{\frac{\alpha}{2}}}{c^{\frac{({\alpha+2})}{2}}\log(\frac{2n-1}{ec})}
	\left(\frac{2}{c}{\sqrt{\left(n(n+2\alpha+1)+\frac{n^2}{A^2}\right)}} \right)^{\frac{n}{A}}\left(\frac{ec}{2n-1}\right)^{n}\nonumber\\
&\leq &\frac{C_{\alpha}\left(\frac{ec}{2n-1}\right)^{\frac{\alpha}{2}}}{c^{\frac{({\alpha+2})}{2}}\log(\frac{2n-1}{ec})}
	\left(\frac{2}{c}n\sqrt{\left(1+\frac{1}{A^2}+\frac{2\alpha}{n}\right)} \right)^{\frac{n}{A}}\left(\frac{(ec)^A}{(2n-1)^A}\right)^{\frac{n}{A}}\nonumber\\
&\leq &\frac{C_{\alpha}\left(\frac{ec}{2n-1}\right)^{\frac{\alpha}{2}}}{c^{\frac{({\alpha+2})}{2}}\log(\frac{2n-1}{ec})}
	\left(\frac{2}{c}n\sqrt{1+\frac{1}{A^2}+\frac{2\alpha+1}{n}}\frac{(ec)^A}{(2n-1)^A}
\right)^{\frac{n}{A}}\nonumber\\
&\leq &\frac{C_{\alpha}\left(\frac{ec}{2n-1}\right)^{\frac{\alpha}{2}}}{c^{\frac{({\alpha+2})}{2}}\log(\frac{2n-1}{ec})}
	\left(2e^Ac^{A-1}\left(\frac{n}{2n-1}\right)^A\sqrt{1+\frac{1}{A^2}+\frac{2\alpha+1}{n}}n^{1-A}
\right)^{\frac{n}{A}}.
	\end{eqnarray}
For the appropriate value of $A=1,9$. We have
\begin{eqnarray}

  |\beta_k^n| &\leq &\frac{C_{\alpha}\left(\frac{ec}{2n-1}\right)^{\frac{\alpha}{2}}}{c^{\frac{({\alpha+2})}{2}}\log(\frac{2n-1}{ec})}
	\left(\frac{1}{2}e^{\frac{A}{A-1}}\left(1+\frac{1}{A^2}+\frac{2\alpha+1}{A}\right)^{\frac{1}{2(A-1)}}\frac{c}{n}
\right)^{\frac{n(A-1)}{A}}\nonumber\\
&\leq &\frac{C_{\alpha}\left(\frac{ec}{2n-1}\right)^{\frac{\alpha}{2}}}{c^{\frac{({\alpha+2})}{2}}\log(\frac{2n-1}{ec})}
	\left(4.13\left(1.28+\frac{2\alpha+1}{1.9}\right)^{0.55}\frac{c}{n}
\right)^{0.47n}.
\end{eqnarray}
Since for all $n\geq m_{\alpha}c$, with $m_{\alpha}=4.13\left(1.28+\frac{2\alpha+1}{1.9}\right)^{0.55}$ there  are two positive  constant $\delta>0$ and
$C_{c,\alpha}\geq \frac{C_{\alpha}\left(\frac{ec}{2n-1}\right)^{\frac{\alpha}{2}}}{c^{\frac{({\alpha+2})}{2}}\log(\frac{2n-1}{ec})}$.
Then we have  \eqref{10}

